//! Sample game: one mesh per reference material from `quillshade/material/` and scene lighting from
//! `quillshade/light/`, generated by shader-editor.
//!
//! Everything comes from the generated baked API (design §3.1, §9.2): `QuillshadeLoader::load()` at startup, the
//! reserved handles of `BakedMaterials`, the images of `BakedTextures`, and `quillshade::light::Light` (`Preset::Day`
//! at startup; press `Space` to transition smoothly between `Preset::Day` and `Preset::Night` using `Curve::Smooth`).
//! Parameter values are the graph and environment defaults (compiled in, overlaid by
//! `assets/quillshade/{material,light}/autogen/baked.ron`); the game never constructs a material or manual light.
//!
//! Run with `cargo run` inside `examples/sample_game`; edit graphs, environments, curves, or Texture assets in the
//! editor while it runs — Bevy's file watcher hot-reloads the regenerated `.wesl` files and manifests.
//!
//! `SAMPLE_SCREENSHOT=out cargo run` saves `out-1.png` 5 s and `out-2.png` 25 s (wall clock, `std::time::Instant`)
//! after the first frame, then exits once `out-2.png` is written. In this mode the window updates continuously even
//! when it is unfocused or hidden and does not wait for vsync, so the timers advance under software rendering too. Edit
//! and regenerate between the two shots to check hot reload.
//!
//! Adding `SAMPLE_LIGHT_PROBE=<raw_t>` (for example `SAMPLE_LIGHT_PROBE=0.3`, honored with `SAMPLE_SCREENSHOT`) freezes
//! virtual and real `Time` via `TimeUpdateStrategy::ManualDuration`, starts a `Preset::Day -> Preset::Night` transition
//! over `Curve::Smooth` (200 ms), steps it once to `raw_t`, and logs `light probe: raw_t=<raw_t> s=<s>` whenever the
//! linear or curve-sampled progress changes (including when `baked.ron` hot-reloads the curve).

use std::time::{Duration, Instant};

use bevy::prelude::*;
use bevy::render::view::screenshot::{Screenshot, ScreenshotCaptured, save_to_disk};
use bevy::sprite_render::SpriteMaterial;
use bevy::time::TimeUpdateStrategy;
use bevy::window::PresentMode;
use bevy::winit::WinitSettings;
use quillshade::data::{Book, Data, Enchantment, LibraryRules, ToShortViewString};
use quillshade::light::{Curve, Light, Preset, State};
use quillshade::material::{BakedMaterials, BakedTextures};
use quillshade::{QuillshadeLoader, QuillshadeProgress, QuillshadeReady};

/// `SAMPLE_SCREENSHOT` shots: (file suffix, seconds of wall-clock time after the first frame).
const SHOTS: [(u32, f64); 2] = [(1, 5.0), (2, 25.0)];

fn main() {
    let screenshot = std::env::var("SAMPLE_SCREENSHOT").ok();
    let probe_raw_t = screenshot.as_ref().and_then(|_| {
        std::env::var("SAMPLE_LIGHT_PROBE")
            .ok()
            .and_then(|s| s.parse::<f32>().ok())
            .filter(|t| t.is_finite())
            .map(|t| t.clamp(0.0, 1.0))
    });
    let present_mode = if screenshot.is_some() { PresentMode::AutoNoVsync } else { PresentMode::default() };
    let mut app = App::new();
    app.add_plugins(DefaultPlugins.set(WindowPlugin {
        primary_window: Some(Window { title: "shader-editor sample".into(), present_mode, ..default() }),
        ..default()
    }))
    .add_plugins(quillshade::QuillshadePlugin)
    .add_systems(Startup, (load_baked, setup).chain())
    .add_systems(Update, (rotate, toggle_light, sync_library_shelf, log_loading, screenshot_and_exit))
    .add_systems(OnEnter(State::Day), || info!("lighting preset settled: Day"))
    .add_systems(OnEnter(State::Night), || info!("lighting preset settled: Night"));
    if let Some(prefix) = screenshot {
        app.insert_resource(WinitSettings::continuous()).insert_resource(ScreenshotRun {
            prefix,
            started_at: None,
            next: 0,
        });
    }
    if let Some(raw_t) = probe_raw_t {
        app.insert_resource(TimeUpdateStrategy::ManualDuration(Duration::ZERO))
            .insert_resource(LightProbe { raw_t })
            .add_systems(Update, light_probe);
    }
    app.run();
}

/// Starts loading all enabled Quillshade domains: `BakedMaterials` handles are usable right away, `BakedTextures` after this.
/// Optional — `QuillshadePlugin` starts loading in the first `PreUpdate` otherwise — but `setup` reads `BakedTextures`.
fn load_baked(mut loader: QuillshadeLoader) {
    info!("quillshade assets: loading {}", loader.load());
}

/// A loading screen would show this; materials render as soon as their images arrive either way.
fn log_loading(mut progress: MessageReader<QuillshadeProgress>, mut ready: MessageReader<QuillshadeReady>) {
    for p in progress.read() {
        info!("quillshade loading: {} / {} ({} failed)", p.loaded, p.total, p.failed);
    }
    if ready.read().count() > 0 {
        info!("quillshade assets ready");
    }
}

#[derive(Resource)]
struct ScreenshotRun {
    prefix: String,
    /// Wall-clock instant of the first frame.
    started_at: Option<Instant>,
    /// Index into `SHOTS` of the next screenshot.
    next: usize,
}

fn screenshot_and_exit(run: Option<ResMut<ScreenshotRun>>, mut commands: Commands) {
    let Some(mut run) = run else { return };
    let start = *run.started_at.get_or_insert_with(Instant::now);
    let Some(&(i, at)) = SHOTS.get(run.next) else { return };
    if start.elapsed().as_secs_f64() < at {
        return;
    }
    run.next += 1;
    let mut shot = commands.spawn(Screenshot::primary_window());
    shot.observe(save_to_disk(format!("{}-{i}.png", run.prefix)));
    if run.next == SHOTS.len() {
        // `save_to_disk` writes synchronously in its observer; the app exits at the end of this frame.
        shot.observe(|_: On<ScreenshotCaptured>, mut exit: MessageWriter<AppExit>| {
            exit.write(AppExit::Success);
        });
    }
}

#[derive(Resource, Clone, Copy)]
struct LightProbe {
    raw_t: f32,
}

fn light_probe(
    probe: Res<LightProbe>,
    mut strategy: ResMut<TimeUpdateStrategy>,
    mut light: Light,
    mut step: Local<u32>,
    mut last_logged: Local<Option<(f32, f32)>>,
) {
    match *step {
        0 => {
            light.transition_to(Preset::Night, Curve::Smooth, Duration::from_millis(200));
            *strategy = TimeUpdateStrategy::ManualDuration(Duration::from_secs_f32(0.2 * probe.raw_t));
            *step = 1;
        }
        1 => {
            *strategy = TimeUpdateStrategy::ManualDuration(Duration::ZERO);
            *step = 2;
            log_light_probe(&light, &mut last_logged);
        }
        _ => {
            log_light_probe(&light, &mut last_logged);
        }
    }
}

fn log_light_probe(light: &Light, last_logged: &mut Option<(f32, f32)>) {
    let raw_t = light.progress();
    let s = light.sampled_progress();
    if last_logged.is_some_and(|(prev_r, prev_s)| (raw_t - prev_r).abs() <= 1e-5 && (s - prev_s).abs() <= 1e-5) {
        return;
    }
    *last_logged = Some((raw_t, s));
    println!("light probe: raw_t={raw_t:.3} s={s:.3}");
}

#[derive(Component)]
struct Spin;

fn setup(
    mut commands: Commands,
    mut meshes: ResMut<Assets<Mesh>>,
    baked: Res<BakedMaterials>,
    tex: Res<BakedTextures>,
    mut light: Light,
) {
    commands
        .spawn((Camera3d::default(), Transform::from_xyz(0.0, 3.0, 9.0).looking_at(Vec3::new(0.0, 0.5, 0.0), Vec3::Y)));
    commands.spawn((Camera2d, Camera { order: 1, clear_color: ClearColorConfig::None, ..default() }));
    light.set_immediate(Preset::Day);

    // Texture assets `textures/rock_albedo` (`.ktx2`) and `textures/rock_normal` (`.png`, `is_srgb: false`).
    let sphere = meshes.add(Sphere::new(1.0).mesh().uv(48, 24).with_generated_tangents().expect("tangents"));
    commands.spawn((
        Mesh3d(sphere.clone()),
        MeshMaterial3d(baked.env.rock_wet.clone()),
        Transform::from_xyz(-3.5, 1.0, 0.0),
        Spin,
    ));
    commands.spawn((
        Mesh3d(sphere.clone()),
        MeshMaterial3d(baked.env.exp42.clone()),
        Transform::from_xyz(0.0, 1.0, 0.0),
        Spin,
    ));
    // Grass on top, rock on the slopes: two `MaterialAttributes (PBR)` layers blended by `WorldAlignedBlend`.
    commands.spawn((
        Mesh3d(sphere.clone()),
        MeshMaterial3d(baked.env.terrain_layers.clone()),
        Transform::from_xyz(2.0, 0.8, 2.5).with_scale(Vec3::splat(0.8)),
    ));
    // Fixed textures inside functions (`common/tex_layer`, called directly and through `common/tex_layer_outer`).
    commands.spawn((
        Mesh3d(sphere.clone()),
        MeshMaterial3d(baked.env.tex_layers.clone()),
        Transform::from_xyz(-1.5, 0.45, 2.8).with_scale(Vec3::splat(0.45)),
        Spin,
    ));

    // `textures/water_normal`: `.ktx2`, `is_srgb: false`, repeating sampler.
    let plane =
        meshes.add(Plane3d::default().mesh().size(4.0, 4.0).build().with_generated_tangents().expect("tangents"));
    commands.spawn((Mesh3d(plane), MeshMaterial3d(baked.env.water.clone()), Transform::from_xyz(0.0, 0.0, 0.0)));

    let cloth = meshes.add(Plane3d::new(Vec3::Z, Vec2::new(1.0, 0.6)).mesh().subdivisions(24).build());
    commands.spawn((Mesh3d(cloth), MeshMaterial3d(baked.env.flag.clone()), Transform::from_xyz(3.0, 1.5, 0.0)));

    commands.spawn((
        Mesh3d(meshes.add(Cylinder::new(0.6, 1.6))),
        MeshMaterial3d(baked.fx.hologram.clone()),
        Transform::from_xyz(0.0, 1.2, -2.0),
    ));

    // `textures/atlas` with a Nearest sampler (switch it to Linear in the editor to see the sampler hot-reload).
    commands.spawn((
        Mesh3d(meshes.add(Cuboid::new(1.0, 1.0, 1.0))),
        MeshMaterial3d(baked.fx.coords.clone()),
        Transform::from_xyz(0.0, 2.8, 0.0),
        Spin,
    ));

    // Bands shaped by the curve assets `common/pulse` and `common/steps`.
    commands.spawn((
        Mesh3d(meshes.add(Plane3d::new(Vec3::Z, Vec2::new(0.9, 0.6)).mesh().build())),
        MeshMaterial3d(baked.fx.curve_bands.clone()),
        Transform::from_xyz(3.3, 3.3, 0.0),
    ));

    // Colors, stripes and the striped branch come from the global constants of `common/tuning`.
    commands.spawn((
        Mesh3d(meshes.add(Plane3d::new(Vec3::Z, Vec2::new(0.9, 0.6)).mesh().build())),
        MeshMaterial3d(baked.fx.global_tint.clone()),
        Transform::from_xyz(-3.3, 3.3, 0.0),
    ));

    // The sprite image comes from `BakedTextures` (filled by `load()`), so its Texture asset settings apply; a plain
    // `assets.load` of the same file could win Bevy's "first load wins" and drop them.
    commands.spawn((
        Sprite::from_image(tex.textures.sprite.clone()),
        SpriteMaterial(baked.ui.dissolve.clone()),
        Transform::from_xyz(-500.0, 250.0, 0.0).with_scale(Vec3::splat(2.0)),
    ));

    // 2D HUD overlay for the Data domain library shelf (`quillshade::data`).
    commands
        .spawn((
            Node {
                position_type: PositionType::Absolute,
                right: Val::Px(14.0),
                top: Val::Px(14.0),
                padding: UiRect::axes(Val::Px(12.0), Val::Px(10.0)),
                border: UiRect::all(Val::Px(1.0)),
                ..default()
            },
            BackgroundColor(Color::srgba(0.08, 0.09, 0.12, 0.84)),
            BorderColor::all(Color::srgba(0.32, 0.36, 0.46, 0.85)),
        ))
        .with_children(|parent| {
            parent.spawn((
                LibraryHudText,
                Text::new("Loading library catalog..."),
                TextFont::from_font_size(13.0),
                TextColor(Color::srgb(0.90, 0.92, 0.96)),
            ));
        });
}

#[derive(Component)]
struct LibraryShelfEntity;

#[derive(Component)]
struct LibraryHudText;

#[derive(Clone, PartialEq)]
struct LibrarySnapshot {
    rules: LibraryRules,
    books: Vec<(u128, Book)>,
}

fn sync_library_shelf(
    mut commands: Commands,
    data: Data,
    mut meshes: ResMut<Assets<Mesh>>,
    mut materials: ResMut<Assets<StandardMaterial>>,
    existing_shelf: Query<Entity, With<LibraryShelfEntity>>,
    mut hud_text: Query<&mut Text, With<LibraryHudText>>,
    mut last: Local<Option<LibrarySnapshot>>,
) {
    if !data.is_ready() || data.collection_library_books_core.is_empty() {
        return;
    }
    let rules = data.collection_library_rules.first().cloned().unwrap_or_default();
    let mut books = Vec::with_capacity(data.collection_library_books_core.len);
    for (id, book) in data.collection_library_books_core {
        debug_assert_eq!(data.collection_library_books_core.get(id), Some(book));
        books.push((id.as_u128(), book.clone()));
    }
    let snapshot = LibrarySnapshot { rules: rules.clone(), books };
    if last.as_ref() == Some(&snapshot) {
        return;
    }

    let first_short = snapshot.books.first().map(|(_, b)| b.to_short_view_string()).unwrap_or_default();
    println!(
        "data probe: rules=\"{}\" books={} first=\"{}\"",
        rules.to_short_view_string(),
        snapshot.books.len(),
        first_short
    );

    for entity in &existing_shelf {
        commands.entity(entity).despawn();
    }

    let shelf_origin = Vec3::new(-1.85, 2.05, 0.4);
    let plank_h = 0.06_f32;
    let wood_mat = materials.add(StandardMaterial {
        base_color: Color::srgb(0.36, 0.23, 0.13),
        perceptual_roughness: 0.78,
        ..default()
    });
    commands.spawn((
        LibraryShelfEntity,
        Mesh3d(meshes.add(Cuboid::new(1.65, plank_h, 0.42))),
        MeshMaterial3d(wood_mat),
        Transform::from_translation(shelf_origin),
    ));

    let count = snapshot.books.len();
    let spacing = rules.shelf_spacing_m.max(0.05);
    let x_start = -((count.saturating_sub(1) as f32) * spacing) * 0.5;
    for (idx, (_row_id, book)) in snapshot.books.iter().enumerate() {
        let size = book.dimensions_cm * 0.01 * rules.book_scale;
        let w = size.z.max(0.04);
        let h = size.y.max(0.08);
        let d = size.x.max(0.06);
        let wear = book.wear_curve.sample(0.25).clamp(0.0, 1.0);
        let spine_col = book.spine_gradient.sample(0.5);
        let blended_tint = Color::from(LinearRgba::from(book.cover_tint).mix(&LinearRgba::from(spine_col), 0.25));
        let emissive = if book.is_rare_edition {
            LinearRgba::from(blended_tint) * (rules.rare_glow_boost * (0.5 + 0.5 * wear))
        } else {
            LinearRgba::BLACK
        };
        let mat = materials.add(StandardMaterial {
            base_color: blended_tint,
            emissive,
            base_color_texture: book.seal_texture.clone(),
            perceptual_roughness: if book.is_rare_edition { 0.28 } else { 0.65 },
            metallic: if book.is_rare_edition { 0.25 } else { 0.04 },
            ..default()
        });
        let pos = shelf_origin + Vec3::new(x_start + (idx as f32) * spacing, plank_h * 0.5 + h * 0.5, 0.0);
        commands.spawn((
            LibraryShelfEntity,
            Mesh3d(meshes.add(Cuboid::new(w, h, d))),
            MeshMaterial3d(mat),
            Transform::from_translation(pos),
        ));
    }

    if let Ok(mut text) = hud_text.single_mut() {
        let ascii = |s: &str| s.replace(" · ", " | ").replace('—', "-");
        let featured = rules.featured_book.resolve(&data).map(|b| b.title.as_str()).unwrap_or("-");
        let total_quota: u32 = rules.shelf_quotas.values().copied().sum();
        let quotas_str = rules
            .shelf_quotas
            .iter()
            .map(|(tag, cap)| format!("{}:{cap}", tag.to_short_view_string()))
            .collect::<Vec<_>>()
            .join(", ");
        let mut lines = Vec::with_capacity(snapshot.books.len() + 2);
        lines.push(format!(
            "{} (loan {}d | fee {:.1}/d | Featured: {})",
            ascii(&rules.shelf_label),
            rules.max_loan_days,
            rules.late_fee_coins_per_day,
            ascii(featured),
        ));
        lines.push(format!("Quotas ({total_quota} total): [{quotas_str}]"));
        for (_id, book) in &snapshot.books {
            let bullet = if book.is_rare_edition { "*" } else { "-" };
            let preset_lbl = match book.reading_ambience {
                Some(Preset::Day) => "Day",
                Some(Preset::Night) => "Night",
                None => "-",
            };
            let ench_lbl = match &book.enchantment {
                Enchantment::Unenchanted => "Unenchanted".to_string(),
                Enchantment::Ward { strength, school } => format!("Ward({strength:.2}, {})", school.as_str()),
                Enchantment::ChronoLock { seal_duration, paradox_safe } => {
                    format!("ChronoLock({:.0}s, safe={paradox_safe})", seal_duration.as_secs_f32())
                }
            };
            let tags_lbl = book.tags.iter().map(ToShortViewString::to_short_view_string).collect::<Vec<_>>().join("+");
            let companion_suffix = match book.companion_volume.resolve(&data) {
                Some(comp) => format!(" -> {}", ascii(&comp.title)),
                None => String::new(),
            };
            let errata_suffix = match &book.errata_note {
                Some(note) => format!(" [Errata: {}]", ascii(note.as_str())),
                None => String::new(),
            };
            lines.push(format!(
                "{bullet} {} ({:.2} kg, {preset_lbl}, {} ch, {ench_lbl}, [{tags_lbl}]){companion_suffix}{errata_suffix}",
                ascii(&book.to_short_view_string()),
                book.weight_kg,
                book.chapters.len(),
            ));
        }
        **text = lines.join("\n");
    }

    *last = Some(snapshot);
}

fn rotate(time: Res<Time>, mut q: Query<&mut Transform, With<Spin>>) {
    for mut t in &mut q {
        t.rotate_y(time.delta_secs() * 0.4);
    }
}

fn toggle_light(keys: Res<ButtonInput<KeyCode>>, mut light: Light) {
    if keys.just_pressed(KeyCode::Space) {
        let next = match light.next_preset().or(light.current_preset()) {
            Some(Preset::Day) => Preset::Night,
            _ => Preset::Day,
        };
        light.transition_to(next, Curve::Smooth, Duration::from_secs(3));
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use bevy::ecs::system::RunSystemOnce;
    use quillshade::data::{BookTag, DataDomainPlugin, DataStore, collections};

    #[test]
    fn sample_game_data_collection_handles_iterate_and_lookup_by_uuid() {
        let mut app = App::new();
        app.add_plugins(DataDomainPlugin);
        app.update();

        // Before `.qsd` files are loaded, compile-time `.len` is already populated while iteration yields 0 rows.
        app.world_mut()
            .run_system_once(|data: Data| {
                assert_eq!(data.collection_library_books_core.len, collections::col_library_books_core::LEN);
                assert_eq!(data.collection_library_books_core.len(), 5);
                assert_eq!(data.collection_library_books_core.into_iter().count(), 0);
                assert!(data.collection_library_rules.first().is_none());
            })
            .unwrap();

        let books_qsd = std::fs::read("assets/quillshade/data/autogen/library/books_core.collection.qsd").unwrap();
        let rules_qsd = std::fs::read("assets/quillshade/data/autogen/library/library_rules.collection.qsd").unwrap();
        {
            let mut store = app.world_mut().resource_mut::<DataStore>();
            store
                .apply_collection_bytes(
                    collections::LIBRARY_BOOKS_CORE,
                    collections::col_library_books_core::BAKED_PATH,
                    &books_qsd,
                )
                .unwrap();
            store
                .apply_collection_bytes(
                    collections::LIBRARY_LIBRARY_RULES,
                    collections::col_library_library_rules::BAKED_PATH,
                    &rules_qsd,
                )
                .unwrap();
        }

        app.world_mut()
            .run_system_once(|data: Data| {
                assert!(data.is_ready());
                assert_eq!(data.collection_library_books_core.len, 5);
                assert_eq!(data.collection_library_books_core.len(), 5);

                let mut seen = 0;
                for (id, book) in data.collection_library_books_core {
                    seen += 1;
                    assert_eq!(data.collection_library_books_core.get(id), Some(book));
                    let id_str = id.to_string();
                    assert_eq!(data.collection_library_books_core.get(id_str.as_str()), Some(book));
                    assert!(!book.wear_curve.points.is_empty());
                    assert!(!book.spine_gradient.stops.is_empty());
                    assert!(book.cover_material.is_some());
                    assert!(book.seal_texture.is_some());
                    assert!(book.reading_ambience.is_some());
                    assert!(!book.tags.is_empty());
                    assert!(book.chapters.len() >= 2);
                }
                assert_eq!(seen, data.collection_library_books_core.len);

                let iter_ids: Vec<_> = data.collection_library_books_core.iter().map(|(id, _)| id).collect();
                assert_eq!(iter_ids.len(), 5);

                let rules = data.collection_library_rules.first().expect("1-row library rules loaded");
                assert_eq!(rules.shelf_label.as_str(), "Grand Archive - Shelf A");
                assert_eq!(rules.featured_book.resolve(&data).map(|b| b.title.as_str()), Some("Codex of Emberlight"));
                assert_eq!(rules.shelf_quotas.get(&BookTag::Alchemy), Some(&12));
                assert_eq!(rules.shelf_quotas.get(&BookTag::Forbidden), Some(&3));
            })
            .unwrap();
    }
}
